#!/usr/bin/env python3

import os
import sys
import shutil
import subprocess
import argparse
from pathlib import Path

def check_root_privileges():
    """Check if the script is running with root privileges"""
    if os.geteuid() != 0:
        print("Error: This script requires root privileges to modify system configuration files.")
        print("Please run with sudo: sudo python3 reset.py")
        return False
    return True

def get_package_manager():
    """Detect the system's package manager"""
    if shutil.which("apt"):
        return "apt"
    elif shutil.which("yum"):
        return "yum"
    elif shutil.which("dnf"):
        return "dnf"
    elif shutil.which("pacman"):
        return "pacman"
    else:
        return None

def reinstall_package_config(package_name):
    """Reinstall package to restore default configuration files"""
    pkg_manager = get_package_manager()

    if not pkg_manager:
        print(f"Unknown package manager. Cannot restore {package_name}")
        return False

    try:
        if pkg_manager == "apt":
            # For APT, we use --reinstall to restore config files
            result = subprocess.run(["apt", "install", "--reinstall", "-o", "Dpkg::Options::=--force-confmiss", "-y", package_name], 
                                  capture_output=True, text=True)
        elif pkg_manager in ["yum", "dnf"]:
            # For YUM/DNF, we can reinstall the package
            result = subprocess.run([pkg_manager, "reinstall", "-y", package_name], 
                                  capture_output=True, text=True)
        elif pkg_manager == "pacman":
            # For Pacman, we can use --force to reinstall
            result = subprocess.run(["pacman", "-S", "--noconfirm", "--force", package_name], 
                                  capture_output=True, text=True)

        if result.returncode == 0:
            print(f"Successfully restored default configurations for {package_name}")
            return True
